const staticData = $getWorkflowStaticData('global');
if (!staticData.alertedRunIds) staticData.alertedRunIds = {};

const response = $input.first().json;
const runs = response.data || [];
const now = Date.now();
const ALERT_TTL = 7 * 24 * 60 * 60 * 1000;

for (const [id, ts] of Object.entries(staticData.alertedRunIds)) {
  if (now - ts > ALERT_TTL) delete staticData.alertedRunIds[id];
}

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const items = [];
for (const r of runs) {
  if (r.status !== 'failed') continue;
  const runKey = String(r.id);
  if (staticData.alertedRunIds[runKey]) continue;
  staticData.alertedRunIds[runKey] = now;

  const errorMsg = r.error || 'unknown error';
  const incident_key = `${r.step}:failed:${runKey}`;

  items.push({
    json: {
      incident_id: uuidv4(),
      incident_key,
      severity: 'high',
      source: 'pipeline-runs-monitor',
      step: r.step,
      timestamp: new Date().toISOString(),
      summary: `Pipeline step failed: ${r.step}`,
      error: errorMsg,
      context: {
        step: r.step,
        pipeline_run_id: r.id,
        run_id: r.run_id,
        started_at: r.started_at,
        finished_at: r.finished_at,
        counts: r.counts,
        poll_url: `/internal/steps/${r.id}`,
      },
    },
  });
}

return items;

